query:
DELETE FROM article_votes WHERE visitorId LIKE 'seed_%';

INSERT INTO article_votes (articleId, reaction, visitorId, createdAt) 
SELECT a.id, r.reaction, CONCAT('seed_', a.id, '_', r.reaction, '_', n.num), NOW() - INTERVAL FLOOR(RAND() * 30) DAY
FROM articles a
CROSS JOIN (SELECT 'loved' as reaction UNION ALL SELECT 'loved' UNION ALL SELECT 'loved' UNION ALL SELECT 'loved' UNION ALL SELECT 'loved' UNION ALL SELECT 'loved' UNION ALL SELECT 'loved' UNION ALL SELECT 'loved' UNION ALL SELECT 'loved' UNION ALL SELECT 'loved') r
CROSS JOIN (SELECT 1 as num UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5) n;

